# CloudFront — the HTTPS front for the ALB (#1345).
#
# Cognito requires redirect URIs to be HTTPS (http:// is allowed only for
# localhost), so the original HTTP-only-ALB design could never complete an
# OIDC sign-in. With no custom domain chosen (that decision stands), the
# cheapest valid HTTPS origin is CloudFront's own *.cloudfront.net domain with
# the default certificate — additive to swap out later: pick a domain, add an
# ACM cert + alias here, and the ALB/ECS layers don't change.
#
# This is a pass-through, not a CDN in anger: the default behavior disables
# caching entirely (the app is a dynamic SPA + API; index.html must never be
# stale, /api must never be cached) and forwards the full request via the
# managed AllViewer policy. Static-asset caching can be added as a dedicated
# /assets/* behavior later if it ever matters — nginx already serves
# fingerprinted files.

data "aws_cloudfront_cache_policy" "caching_disabled" {
  name = "Managed-CachingDisabled"
}

data "aws_cloudfront_origin_request_policy" "all_viewer" {
  name = "Managed-AllViewer"
}

resource "aws_cloudfront_distribution" "app" {
  enabled         = true
  comment         = "DataQ frontend — HTTPS front for the ALB (no custom domain)"
  is_ipv6_enabled = true
  # Cheapest edge-location class (NA + EU) — this is an HTTPS terminator, not
  # a latency play.
  price_class = "PriceClass_100"

  origin {
    domain_name = aws_lb.app.dns_name
    origin_id   = "alb"

    custom_origin_config {
      http_port  = 80
      https_port = 443
      # The ALB listener is plain HTTP :80; TLS terminates at CloudFront. The
      # ALB is not internet-reachable in practice — its security group admits
      # only CloudFront's origin-facing address ranges (alb.tf).
      origin_protocol_policy = "http-only"
      origin_ssl_protocols   = ["TLSv1.2"]
    }
  }

  default_cache_behavior {
    target_origin_id       = "alb"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true

    cache_policy_id          = data.aws_cloudfront_cache_policy.caching_disabled.id
    origin_request_policy_id = data.aws_cloudfront_origin_request_policy.all_viewer.id
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = { Name = "dataq-app-cloudfront" }
}

# ALB behind CloudFront (#1345) — CloudFront is the sole public surface
# (ADR 0028 §5's api-goes-internal posture, one hop further out). Only the
# frontend target group exists; api/worker have no ALB listener and are
# reached only via Cloud Map internal DNS (ecs.tf).
#
# The listener stays plain HTTP :80: TLS terminates at CloudFront (Cognito
# requires an HTTPS redirect URI, and there is no custom domain — see
# cloudfront.tf). The security group admits only CloudFront's origin-facing
# ranges (AWS-managed prefix list), so the ALB cannot be reached directly —
# which also closes the "bypass CloudFront to talk plain HTTP" hole.

# AWS-managed, auto-updated list of CloudFront origin-facing IP ranges.
data "aws_ec2_managed_prefix_list" "cloudfront_origin" {
  name = "com.amazonaws.global.cloudfront.origin-facing"
}

resource "aws_security_group" "alb" {
  name        = "dataq-app-alb"
  description = "ALB — inbound HTTP from CloudFront origin-facing ranges only"
  vpc_id      = aws_vpc.app.id

  ingress {
    description     = "HTTP from CloudFront"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    prefix_list_ids = [data.aws_ec2_managed_prefix_list.cloudfront_origin.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "dataq-app-alb" }
}

resource "aws_lb" "app" {
  name               = "dataq-app"
  internal           = false
  load_balancer_type = "application"
  subnets            = aws_subnet.public[*].id
  security_groups    = [aws_security_group.alb.id]

  tags = { Name = "dataq-app-alb" }
}

resource "aws_lb_target_group" "frontend" {
  name        = "dataq-app-frontend"
  port        = 8080
  protocol    = "HTTP"
  vpc_id      = aws_vpc.app.id
  target_type = "ip" # required for Fargate tasks (no EC2 instance id)

  health_check {
    path                = "/healthz"
    healthy_threshold   = 2
    unhealthy_threshold = 3
    interval            = 15
    timeout             = 5
  }

  tags = { Name = "dataq-app-frontend" }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.app.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.frontend.arn
  }
}

locals {
  # No custom domain yet — CloudFront's own domain is the deployment's public
  # HTTPS URL (#1345). Depends only on the distribution (which depends only on
  # the ALB), so nothing later in the graph waits on the ECS service itself —
  # mirroring the Azure stack's deterministic-FQDN trick that breaks the
  # frontend<->api circular dependency.
  frontend_url     = "https://${aws_cloudfront_distribution.app.domain_name}"
  api_internal_url = "http://api.dataq.local:8000"
}

# GitHub Actions -> AWS auth for the Deploy workflow — OIDC federation, no
# stored access keys. Mirrors deploy/terraform/azure/github_oidc.tf's shape:
# an OIDC identity provider trusting token.actions.githubusercontent.com, and
# a role whose trust policy conditions on the exact repo+environment subject.

# GitHub's OIDC token-signing certificate thumbprint. AWS's OIDC provider
# resource requires this argument, though AWS has stopped strictly validating
# it against the TLS chain for well-known providers — kept for API
# compatibility. Verify at apply time against
# https://token.actions.githubusercontent.com/.well-known/openid-configuration
# if GitHub ever rotates their intermediate CA.
locals {
  github_oidc_thumbprint = "6938fd4d98bab03faadb97b34396831e3780aea1"
}

resource "aws_iam_openid_connect_provider" "github" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = [local.github_oidc_thumbprint]
}

data "aws_iam_policy_document" "github_deploy_assume" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }
    # Must match the workflow's `environment: production` job scoping —
    # exactly the same shape as the Azure federated-credential subject.
    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${var.github_repo}:environment:${var.github_environment}"]
    }
  }
}

resource "aws_iam_role" "github_deploy" {
  name               = "dataq-app-github-deploy"
  assume_role_policy = data.aws_iam_policy_document.github_deploy_assume.json
}

# Least privilege, resource-scoped to exactly the ECS objects the Deploy
# workflow touches (update-service / run-task for the migrate task) — never
# account-wide. iam:PassRole is scoped to only the task/execution roles this
# stack created, so the CI principal cannot pass an arbitrary role to a task.
data "aws_iam_policy_document" "github_deploy" {
  # Two statements, split by whether the action populates the `ecs:cluster`
  # condition key (#1348). Task-definition actions are not cluster-scoped and
  # never set the key, so putting them under the ArnEquals condition made the
  # condition evaluate against a MISSING key — an implicit deny that would
  # have failed the workflow's first `register-task-definition`.
  statement {
    sid = "EcsDeployClusterScoped"
    actions = [
      "ecs:UpdateService",
      "ecs:DescribeServices",
      "ecs:RunTask",
      "ecs:DescribeTasks",
    ]
    resources = ["*"]
    condition {
      test     = "ArnEquals"
      variable = "ecs:cluster"
      values   = [aws_ecs_cluster.app.arn]
    }
  }

  statement {
    sid = "EcsTaskDefinitions"
    actions = [
      "ecs:RegisterTaskDefinition",
      "ecs:DescribeTaskDefinition",
    ]
    # `*` is the best available scoping: the task-definition action family
    # supports no resource-level restriction (registration creates a NEW
    # revision ARN). The blast radius stays contained by the PassTaskRoles
    # statement below — a registered definition is inert unless it can be run,
    # and running it needs a role this policy will only pass for this stack's
    # own task/execution roles, on this stack's cluster.
    resources = ["*"]
  }

  statement {
    sid     = "PassTaskRoles"
    actions = ["iam:PassRole"]
    resources = [
      aws_iam_role.ecs_task_execution.arn,
      aws_iam_role.ecs_task_api.arn,
      aws_iam_role.ecs_task_worker.arn,
    ]
  }
}

resource "aws_iam_role_policy" "github_deploy" {
  name   = "dataq-app-github-deploy"
  role   = aws_iam_role.github_deploy.id
  policy = data.aws_iam_policy_document.github_deploy.json
}

# Non-secret configuration. Defaults are wired for the AWS parallel-deployment
# bring-up. Override in terraform.tfvars (gitignored) — see
# terraform.tfvars.example. Two required inputs have no default and will hang
# OpenTofu on stdin if missing — always pass -input=false.

variable "aws_region" {
  description = "AWS region for every resource in this stack."
  type        = string
  default     = "us-east-2"
}

# ── Database ──────────────────────────────────────────────────────────────

variable "app_db_name" {
  description = "The app's database name."
  type        = string
  default     = "dataq"
}

variable "app_db_user" {
  description = "Least-privilege role the app connects as."
  type        = string
  default     = "dataq_app"
}

variable "app_db_password" {
  description = "Password for app_db_user. Pass at apply: TF_VAR_app_db_password=... . Injected into Secrets Manager as an infra-owned secret; never committed."
  type        = string
  sensitive   = true
}

# ── Images (GHCR — ADR 0023, cloud-agnostic) ────────────────────────────────

variable "backend_image_repo" {
  description = "GHCR backend image repository (public package, anonymous pull)."
  type        = string
  default     = "ghcr.io/theurgicduke771/dataq-backend"
}

variable "frontend_image_repo" {
  description = "GHCR frontend (nginx SPA) image repository — one generic runtime-configured image (ADR 0028)."
  type        = string
  default     = "ghcr.io/theurgicduke771/dataq-frontend"
}

variable "image_tag" {
  description = <<-DESC
    Backend image tag the task definitions are CREATED with (immutable tag —
    a commit SHA from publish-images.yml; later rollouts happen out-of-band
    via CI, ignore_changes on the container image). No default on purpose
    (#1349): the services genuinely RUN this image from the first apply, and
    a stale hardcoded default (the old "v10", a June image predating the
    generic-OIDC auth and the aws_secrets_manager store) crash-loops from
    minute one. Pass the current main SHA at apply:
      -var image_tag=$(git rev-parse origin/main)
  DESC
  type        = string
}

variable "frontend_image_tag" {
  description = "Frontend image tag the task definition is created with. Same no-default reasoning + out-of-band rollout note as image_tag (publish-images.yml pushes backend + frontend under the SAME commit SHA)."
  type        = string
}

# ── App config (non-secret) ──────────────────────────────────────────────

variable "environment" {
  description = "ENVIRONMENT value the backend Settings read."
  type        = string
  default     = "prod"
}

variable "workspace_admin_emails" {
  description = "Comma-separated workspace-admin allowlist (WORKSPACE_ADMIN_EMAILS)."
  type        = string
  default     = ""
}

variable "email_username" {
  description = "SMTP login / sender for the email alert channel. Empty = channel off."
  type        = string
  default     = ""
}

variable "email_from" {
  description = "From: address for email alerts (defaults to email_username when empty)."
  type        = string
  default     = ""
}

variable "email_to" {
  description = "Comma-separated recipients for email alerts. Empty = email channel off."
  type        = string
  default     = ""
}

# ── Secrets (AWS Secrets Manager — SECRET_STORE=aws_secrets_manager) ───────

variable "aws_secrets_manager_prefix" {
  description = "Namespace prefix for datasource-credential secrets the app manages at runtime (AWS_SECRETS_MANAGER_PREFIX). Distinct from the infra-owned bootstrap secrets (DB URL etc.), which live under a separate dataq-app-infra/ prefix this stack owns directly."
  type        = string
  default     = "dataq"
}

# ── Cognito (generic OIDC — core/auth.py OidcBearerScheme) ─────────────────

variable "cognito_callback_path" {
  description = "Path appended to the frontend URL for the OIDC redirect callback (oidc-client-ts default)."
  type        = string
  default     = "/auth/callback"
}

# ── CI deploy (GitHub OIDC) ─────────────────────────────────────────────────

variable "github_repo" {
  description = "owner/repo the Deploy workflow runs from (federated-credential subject)."
  type        = string
  default     = "TheurgicDuke771/DataQ"
}

variable "github_environment" {
  description = "GitHub environment the federated credential is scoped to."
  type        = string
  default     = "production"
}

# ── State encryption (OpenTofu) ─────────────────────────────────────────────

variable "state_encryption_passphrase" {
  description = <<-DESC
    Passphrase for OpenTofu state encryption (versions.tf `encryption` block).

    Supplied from the gitignored terraform.tfvars. This is a DATA-AT-REST KEY,
    not a credential: it cannot be revoked and it cannot be re-minted. Losing
    it means terraform.tfstate is unrecoverable — keep a second copy off this
    machine. See README.md.
  DESC
  type        = string
  sensitive   = true
}

# ── Sizing / retention ───────────────────────────────────────────────────

variable "log_retention_days" {
  description = "CloudWatch Logs retention for every DataQ log group."
  type        = number
  default     = 30
}
